<body>
<header class="navbar">
  <div class="container-wide d-flex align-items-center justify-content-between gap-3">
    <a href="#beranda" class="brand" aria-label="NeuroTrack beranda"><span class="brand-mark">✳</span><span>NeuroTrack</span></a>
