<div class="toast-msg" id="toastMsg" role="status" aria-live="polite"></div>
<script>
  const menuToggle=document.getElementById('menuToggle'),navLinks=document.getElementById('navLinks');
  menuToggle?.addEventListener('click',()=>{const open=navLinks.classList.toggle('open');menuToggle.setAttribute('aria-expanded',String(open));menuToggle.textContent=open?'✕':'☰'});
  navLinks?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{navLinks.classList.remove('open');menuToggle?.setAttribute('aria-expanded','false');if(menuToggle)menuToggle.textContent='☰'}));
  const toast=document.getElementById('toastMsg');let toastTimer;
  function showNotice(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3000)}
  document.querySelectorAll('[data-notice]').forEach(button=>button.addEventListener('click',()=>showNotice(button.dataset.notice)));
  document.getElementById('newsletterForm')?.addEventListener('submit',event=>{event.preventDefault();showNotice('Terima kasih! Form newsletter ini masih berupa demo.');event.target.reset()});
</script>
